"""Render the data dictionary document as Markdown.

Sections are built once and combined three ways: the whole dictionary, the table
reference and the tool reference that ship inside the agent skill.
"""

import json
from typing import Any

Row = dict[str, Any]

NOTICE = (
    "<!-- Generated by `python -m pipeline dictionary`. Edit config/dataset.yaml, "
    "config/api.yaml or the code they describe, not this file. -->"
)


VOCABULARIES = {
    "status": "`status`",
    "kind": "`kind`",
    "match": "`match`",
    "rank_basis": "`rank_basis`",
}
EVIDENCE_VOCABULARIES = {
    "reason": "`evidence.reason`",
    "city_method": "`cells.city_method`",
    "land_method": "`cells.land_method`",
}


def text(value: Any) -> str:
    return str(value).replace("|", "\\|").replace("\n", " ")


def ticks(names: list[str]) -> str:
    return ", ".join(f"`{name}`" for name in names) or "none"


def grid(headers: list[str], rows: list[list[Any]]) -> list[str]:
    lines = ["| " + " | ".join(headers) + " |", "|" + " --- |" * len(headers)]
    lines += ["| " + " | ".join(text(cell) for cell in row) + " |" for row in rows]
    return [*lines, ""]


def entries(items: list[Row], applies: bool = False) -> list[str]:
    lines = []
    for item in items:
        scope = f" ({', '.join(item['applies_to'])})" if applies else ""
        lines.append(f"- `{item['value']}`{scope}: {item['meaning']}")
    return [*lines, ""]


def families(document: Row) -> list[str]:
    lines = [
        "## Pack families",
        "",
        "Each family is an installable pack that answers one kind of question. "
        "Forward families use the `core` pack, when installed, for city and "
        "timezone detail.",
        "",
    ]
    for name, family in document["packs"].items():
        lines += [
            f"### `{name}`",
            "",
            family["answers"],
            "",
            f"- Tools: {ticks(family['tools'])}",
            f"- Inputs: {family['inputs']}",
            f"- Built from tables: {ticks(family['tables'])}",
            f"- Notes: {family['notes']}",
            "",
        ]
    return lines


def tools(document: Row) -> list[str]:
    lines = [
        "## Tools",
        "",
        "Every tool is read-only, never installs data and never uses the network. "
        "Lookup tools return the result object described below.",
        "",
    ]
    for tool in document["tools"]:
        lines += [f"### `{tool['name']}`", "", tool["description"], ""]
        rows = []
        for item in tool["parameters"]:
            default = "" if item["required"] else f"`{json.dumps(item['default'])}`"
            rows.append(
                [
                    f"`{item['name']}`",
                    item["type"],
                    "yes" if item["required"] else "no",
                    default,
                    item["description"],
                ]
            )
        lines += grid(["Parameter", "Type", "Required", "Default", "Description"], rows)
    lines += ["## Resources", ""]
    for resource in document["resources"]:
        kind, note = resource["mime_type"], resource["description"]
        lines.append(f"- `{resource['uri']}` ({kind}): {note}")
    return [*lines, ""]


def fields(items: list[Row], vocabularies: dict[str, str]) -> list[str]:
    rows = []
    for item in items:
        kind = item["type"]
        if item["name"] in vocabularies:
            kind += f" (values: {vocabularies[item['name']]})"
        rows.append([f"`{item['name']}`", kind, item["meaning"]])
    return grid(["Field", "Type", "Meaning"], rows)


def results(document: Row) -> list[str]:
    shape = document["results"]
    lines = [
        "## Result",
        "",
        "Every lookup tool returns one result object. `evidence` appears only when "
        "requested and `hint` only when the input needs correction.",
        "",
        *fields(shape["fields"], VOCABULARIES),
    ]
    for name, items in shape["objects"].items():
        links = EVIDENCE_VOCABULARIES if name == "Evidence" else {}
        lines += [f"### `{name}`", "", *fields(items, links)]
    lines += ["### `status`", "", *entries(shape["status"])]
    lines += ["### `kind`", "", *entries(shape["kind"])]
    lines += ["### `match`", "", *entries(shape["match"])]
    lines += ["### `evidence.reason`", "", *entries(shape["evidence_reason"], True)]
    lines += ["### `rank_basis`", "", *entries(shape["rank_basis"], True)]
    lines += ["### Error codes", ""]
    lines += [f"- `{e['code']}`: {e['meaning']}" for e in shape["errors"]]
    return [*lines, ""]


def table_index(document: Row) -> list[str]:
    rows = [
        [
            f"[`{name}`](#{name})",
            t["grain"],
            ticks(t["primary_key"]),
            ticks(t["used_by"]),
        ]
        for name, t in document["tables"].items()
    ]
    return grid(["Table", "Grain", "Key", "Feeds packs"], rows)


def table_section(name: str, table: Row) -> list[str]:
    key = ticks(table["primary_key"]) if table["primary_key"] else "none"
    lines = [
        f"### `{name}`",
        "",
        table["description"],
        "",
        f"- Grain: {table['grain']}",
        f"- Primary key: {key}"
        + ("" if table["primary_key"] else " (observations can repeat)"),
        f"- Feeds packs: {ticks(table['used_by'])}",
        "",
    ]
    if table["relationships"]:
        lines += ["Joins:", ""]
        for item in table["relationships"]:
            local = ", ".join(f"`{name}.{c}`" for c in item["columns"])
            target = item["references"]
            remote = ", ".join(f"`{target['table']}.{c}`" for c in target["columns"])
            lines.append(f"- {local} \u2192 {remote}: {item['meaning']}")
        lines.append("")
    rows = []
    for column in table["columns"]:
        nullable = "yes" if column["nullable"] else "no"
        if column["nullable"] and column["name"] in table["primary_key"]:
            nullable = "yes in Arrow; no for the logical key"
        units = "" if column["units"] == "none" else column["units"]
        rows.append(
            [
                f"`{column['name']}`",
                f"`{column['type']}`",
                nullable,
                units,
                column["meaning"],
            ]
        )
    lines += grid(["Column", "Type", "Nullable", "Units", "Meaning"], rows)
    coded = [c for c in table["columns"] if c.get("values")]
    if coded:
        lines += ["Enumerated columns:", ""]
        for column in coded:
            lines.append(f"- `{column['name']}`")
            lines += [f"  - `{v['value']}`: {v['meaning']}" for v in column["values"]]
        lines.append("")
    return lines


def tables(document: Row) -> list[str]:
    lines = [
        "## Dataset tables",
        "",
        "Plain Parquet files, one directory per table. Partition labels in "
        "directory names (`country=XX`, `group=...`) are file routing, not columns. "
        "Observation tables keep duplicates; only the keys listed are guaranteed "
        "unique.",
        "",
        *table_index(document),
    ]
    for name, table in document["tables"].items():
        lines += table_section(name, table)
    return lines


def render_tables(document: Row) -> str:
    lines = [NOTICE, "", "# Thereabouts dataset tables", "", *tables(document)]
    return "\n".join(lines).rstrip("\n") + "\n"


def render_tools(document: Row) -> str:
    lines = [NOTICE, "", "# Thereabouts MCP tools and results", ""]
    lines += [*families(document), *tools(document), *results(document)]
    return "\n".join(lines).rstrip("\n") + "\n"


def render_markdown(document: Row) -> str:
    lines = [NOTICE, "", "# Thereabouts data dictionary", "", document["about"], ""]
    lines += [*families(document), *tools(document), *results(document)]
    lines += tables(document)
    return "\n".join(lines).rstrip("\n") + "\n"
